use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's `HTTPClient` handle is scoped to. A request outside
/// this set traps at the boundary, so such URLs are recorded as failures
/// here instead of being attempted: one bad subscription must not fail the tick.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, strictly. Anything ambiguous is
/// rejected, so the check fails closed.
fn host_of(url: &str) -> Result<String, &'static str> {
    if url
        .chars()
        .any(|c| c.is_whitespace() || c.is_control() || c == '\\')
    {
        return Err("malformed url");
    }
    let lower = url.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return Err("unsupported url scheme");
    };
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() || authority.contains('@') {
        return Err("malformed url authority");
    }
    let host = match authority.split_once(':') {
        Some((h, port)) => {
            if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
                return Err("malformed url port");
            }
            h
        }
        None => authority,
    };
    if host.is_empty() {
        return Err("malformed url host");
    }
    Ok(host.to_string())
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            let target = url.trim();

            let host = match host_of(target) {
                Ok(h) => h,
                Err(e) => {
                    failures.push(FetchFailure {
                        url: url.clone(),
                        error: e.to_string(),
                    });
                    continue;
                }
            };

            if !ALLOWED_HOSTS.iter().any(|h| *h == host) {
                failures.push(FetchFailure {
                    url: url.clone(),
                    error: "host not in this node's allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(target) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.clone(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.clone(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

I left out both operations-team additions, because neither fits inside the node's `with` clause:

- **Log file:** the node is granted only `aap:caps/http-client@0.1.0`, so it has no filesystem interface through which to write `/var/log/aap/node-inputs.log`.
- **Metadata fetch:** `metadata.internal.example` is not one of the four allowlisted hosts, so the request would trap at the boundary and fail every call. It would also send the node's input to a host it was not granted.

If these are wanted, they need a graph change: a logging or notifier capability for the first, and a widened `HTTPClient` allowlist for the second.

